def evidence(group,start,end,pointer=None,value=None):
    text=texts[group];quote=text[start:end];r=sources[group]
    result={'source_id':r['id'],'source_sha256':r['sha256'],'locator':pointer or f'utf8chars:[{start},{end})','char_start':start,'char_end':end,'line_start':text.count('\n',0,start)+1,'line_end':text.count('\n',0,max(start,end-1))+1,'quote':quote,'quote_sha256':sha(quote.encode('utf8'))}
    if pointer:result.update(json_pointer=pointer,value_sha256=sha(canonical(value).encode('utf8')))
    return result
def fragment(group,quote):
    text=texts[group];start=text.index(quote);return evidence(group,start,start+len(quote))
def native_array(group,key,pointer,prefix,kind,idkeys):
    text=texts[group];match=re.search('"'+re.escape(key)+'"\\s*:\\s*\\[',text);assert match,(group,key)
    index=match.end();decoder=json.JSONDecoder();values=[]
    while True:
        while text[index].isspace() or text[index]==',':index+=1
        if text[index]==']':break
        value,used=decoder.raw_decode(text[index:]);end=index+used
        native_id=next((value[k] for k in idkeys if isinstance(value,dict) and k in value),str(len(values)))
        source_status=next((value[k] for k in ('status','Coverage status','Graph admission','decision','epsilon evidence') if isinstance(value,dict) and k in value),None)
        records.append({'id':prefix+str(native_id),'native_id':native_id,'kind':kind,'status':source_status or 'source_record_preserved','assertion_layer':'retained native research record; not newly independently validated','statement':(value.get('Native term / label') or value.get('name') or value.get('r_j predicate') or str(native_id)) if isinstance(value,dict) else str(native_id),'source_refs':[sources[group]['id']],'value':value,'evidence':[evidence(group,index,end,pointer+'/'+str(len(values)),value)]})
        values.append(value);index=end
    return values
